args<-commandArgs(TRUE);P<-normalizePath(args[1]);W<-file.path(P,'work/2026-10-28-batch-five/plotgardener');S<-file.path(P,'biofigure')
.libPaths(c(file.path(W,'Rlib'),file.path(P,'work/2026-10-11-next-complex-training/ohca/R-library'),.libPaths()))
suppressPackageStartupMessages({library(plotgardener);library(plotgardenerData);library(TxDb.Hsapiens.UCSC.hg19.knownGene);library(org.Hs.eg.db)})
sha<-function(p)digest::digest(file=p,algo='sha256');bound<-function(p)list(path=normalizePath(p),sha256=sha(p))
files<-list.files(file.path(W,'data/raw'),pattern='rda$',full.names=TRUE);e<-new.env();names<-unlist(lapply(files,function(p)load(p,envir=e)));qc<-list()
for(n in names){d<-get(n,e);write.csv(d,file.path(W,'results/plot_data',paste0(n,'.csv')),row.names=FALSE);qc[[n]]<-list(rows=nrow(d),columns=names(d),na_count=sum(is.na(d)),source=bound(files[match(n,sub('.rda$','',basename(files)))]))}
cyto<-read.table(file.path(W,'data/raw/hg19-cytoBand.txt'),sep='\t',header=FALSE,col.names=c('seqnames','start','end','name','gieStain'));cyto<-subset(cyto,seqnames=='chr21');cyto$start<-cyto$start+1L;cyto$width<-cyto$end-cyto$start+1L;cyto$strand<-'*';cyto<-cyto[,c('seqnames','start','end','width','strand','name','gieStain')];write.csv(cyto,file.path(W,'results/plot_data/hg19_chr21_cytobands.csv'),row.names=FALSE)
txdb<-TxDb.Hsapiens.UCSC.hg19.knownGene;region<-GenomicRanges::GRanges('chr21',IRanges::IRanges(28000000,30300000));tx<-GenomicFeatures::transcriptsByOverlaps(txdb,region,columns=c('tx_id','tx_name','gene_id'));ex<-GenomicFeatures::exonsByOverlaps(txdb,region,columns=c('exon_id','tx_id','gene_id'));flatten<-function(x){d<-as.data.frame(x);for(n in names(d))if(is.list(d[[n]]))d[[n]]<-vapply(d[[n]],paste,character(1),collapse='|');d};write.csv(flatten(tx),file.path(W,'results/plot_data/hg19_chr21_transcripts.csv'),row.names=FALSE);write.csv(flatten(ex),file.path(W,'results/plot_data/hg19_chr21_exons.csv'),row.names=FALSE)
writeLines(capture.output(sessionInfo()),file.path(W,'evidence/sessionInfo.txt'))
qc$cytobands<-list(coordinate_conversion='UCSC zero-based half-open start converted to one-based closed GRanges convention by adding one to start only',rows=nrow(cyto),chromosome='chr21',min=min(cyto$start),max=max(cyto$end));qc$annotation<-list(transcripts=length(tx),exons=length(ex),txdb_file=bound(system.file('extdata','TxDb.Hsapiens.UCSC.hg19.knownGene.sqlite',package='TxDb.Hsapiens.UCSC.hg19.knownGene')),orgdb_file=bound(system.file('extdata','org.Hs.eg.sqlite',package='org.Hs.eg.db')))
qc$scope<-'Author processed real contact counts and ChIP-seq signal tables; hg19 coordinate-local annotation only. No raw sequencing or biological inference.'
jsonlite::write_json(qc,file.path(W,'evidence/input-qc.json'),auto_unbox=TRUE,pretty=TRUE,digits=NA)
